      exception.code === 'SAMPLE_NOT_FOUND' || exception.code === 'BATCH_NOT_FOUND'
        ? HttpStatus.NOT_FOUND
        : HttpStatus.CONFLICT;
    res.status(status).json({ statusCode: status, code: exception.code, message: exception.message });
  }
}

